<?php require_admin();$search=trim($_GET['search']??'');$status=$_GET['status']??'';$category=(int)($_GET['category_id']??0);$priority=$_GET['priority']??'';$categories=db_all('SELECT id,category_name FROM categories ORDER BY category_name');$sql='SELECT c.*,s.name student_name,ca.category_name FROM complaints c JOIN students s ON s.id=c.student_id JOIN categories ca ON ca.id=c.category_id WHERE 1=1';$types='';$params=[];if($search!==''){$sql.=' AND (c.title LIKE ? OR c.complaint_id LIKE ? OR s.name LIKE ?)';$term="%$search%";$types.='sss';array_push($params,$term,$term,$term);}if(in_array($status,['Pending','In Progress','Resolved','Closed','Rejected'],true)){$sql.=' AND c.status=?';$types.='s';$params[]=$status;}if($category>0){$sql.=' AND c.category_id=?';$types.='i';$params[]=$category;}if(in_array($priority,['Low','Medium','High'],true)){$sql.=' AND c.priority=?';$types.='s';$params[]=$priority;}$sql.=' ORDER BY c.created_at DESC';$rows=db_all($sql,$types,$params);$pageTitle='All Complaints';require_once __DIR__.'/../includes/header.php'; ?>
<div class="row g-4"><div class="col-lg-3"><?php require __DIR__.'/_sidebar.php'; ?></div><div class="col-lg-9"><div class="dashboard-header mb-4"><div class="small-muted">ADMINISTRATION</div><h1 class="section-title mb-0">All complaints</h1></div><div class="card mb-4"><div class="card-body"><form class="row g-2"><div class="col-lg-4"><input class="form-control" name="search" value="<?=e($search)?>" placeholder="Search ID, title, or student"></div><div class="col-lg-2"><select class="form-select" name="status"><option value="">Status</option><?php foreach(['Pending','In Progress','Resolved','Closed','Rejected'] as $v): ?><option <?=($status===$v)?'selected':''?>><?=e($v)?></option><?php endforeach;?></select></div><div class="col-lg-2"><select class="form-select" name="priority"><option value="">Priority</option><?php foreach(['Low','Medium','High'] as $v): ?><option <?=($priority===$v)?'selected':''?>><?=e($v)?></option><?php endforeach;?></select></div><div class="col-lg-2"><select class="form-select" name="category_id"><option value="">Category</option><?php foreach($categories as $v): ?><option value="<?=$v['id']?>" <?=($category===$v['id'])?'selected':''?>><?=e($v['category_name'])?></option><?php endforeach;?></select></div><div class="col-lg-2"><button class="btn btn-outline-primary w-100">Filter</button></div></form></div></div><div class="card"><div class="table-responsive"><table class="table"><thead><tr><th>Complaint</th><th>Student</th><th>Category</th><th>Priority</th><th>Status</th></tr></thead><tbody><?php if(!$rows): ?><tr><td colspan="5"><div class="empty-state">No complaints match these filters.</div></td></tr><?php else: foreach($rows as $row): ?><tr><td><a class="complaint-id" href="<?=e(url('admin/complaint.php?id='.$row['id']))?>"><?=e($row['complaint_id'])?></a><div><?=e($row['title'])?></div></td><td><?=e($row['student_name'])?></td><td><?=e($row['category_name'])?></td><td><span class="fw-semibold <?=e(priority_class($row['priority']))?>"><?=e($row['priority'])?></span></td><td><span class="badge-soft <?=e(status_class($row['status']))?>"><?=e($row['status'])?></span></td></tr><?php endforeach; endif; ?></tbody></table></div></div></div></div>
<?php require_once __DIR__.'/../includes/footer.php'; ?>
